 * @param {number} k
 * @return {boolean}
 */
var areSimilar = function(mat, k) {
    const m = mat.length;
    const n = mat[0].length;
    const mv = k % m;

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            const val = c & 1 ? mat[r][(c - mv + n) % n] : mat[r][(c + mv) % n];

            if (val !== mat[r][c]) {
                return false;
            }
        }
    }

    return true;
};

