var areSimilar = function(mat, k) {
    const m = mat.length;
    const n = mat[0].length;
    const mv = k % n;

    for (let row = 0; row < m; row++) {
        for (let col = 0; col < n; col++) {
            const shift = col & 1 ? mv : -mv;
            const nc = (col + shift + n) % n;

            if (mat[row][nc] !== mat[row][col]) {
                return false;
            }
        }
    }

